int main(){ ios::sync_with_stdio(false); cin.tie(nullptr);
  int n; cin >> n; unordered_map<string,int> id; for(int i = 0; i < n; i++){ string s; cin >> s; id[s] = i; }
  int e; cin >> e; vector<vector<pair<int,long long>>> g(n);
  for(int i = 0; i < e; i++){ string u, v; long long w; cin >> u >> v >> w; g[id[u]].push_back({id[v], w}); }
  string A, B; cin >> A >> B; int a = id[A], b = id[B];
  vector<long long> d(n, LLONG_MAX); priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq; d[a] = 0; pq.push({0, a});
  while(!pq.empty()){ auto [du, u] = pq.top(); pq.pop(); if(du > d[u]) continue; for(auto [v, w] : g[u]) if(du + w < d[v]){ d[v] = du + w; pq.push({d[v], v}); } }
  cout << (d[b] == LLONG_MAX ? -1 : d[b]) << "\n"; }

